draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 100, 20, 0, 2*Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 120); // body
  ctx.lineTo(W/2, H/2 + 200);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150); // arm
  ctx.lineTo(W/2 + Math.sin(t)*50, H/2 + 180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 150); // arm
  ctx.lineTo(W/2 - Math.sin(t)*50, H/2 + 180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200); // leg
  ctx.lineTo(W/2 + Math.sin(t)*20, H/2 + 250);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200); // leg
  ctx.lineTo(W/2 - Math.sin(t)*20, H/2 + 250);
  ctx.stroke();

  ctx.restore();
}
